js-proj-02-e3.codigo:
function situacao(media) {
  if (media >= 7) return "Aprovado";
  if (media >= 5) return "Recuperação";
  return "Reprovado";
}

const turma = [
  { nome: "Ana", nota1: 7, nota2: 9 },
  { nome: "Luiz", nota1: 4, nota2: 5 },
  { nome: "Kauan", nota1: 6, nota2: 6 },
];

let somaDasMedias = 0;
let aprovados = 0;

for (const aluno of turma) {
  const media = (aluno.nota1 + aluno.nota2) / 2;
  console.log(`${aluno.nome}: média ${media} - ${situacao(media)}`);
  somaDasMedias += media;
  if (situacao(media) === "Aprovado") {
    aprovados++;
  }
}

console.log("---");
console.log(`Média da turma: ${Math.round((somaDasMedias / turma.length) * 100) / 100}`);
console.log(`Aprovados: ${aprovados} de ${turma.length}`);

